function H.set_mask(e)
  local cb = e.get_control_behavior()
  while cb.sections_count > 0 do cb.remove_section(1) end
  local n = 0
  for _, names in pairs(H.MASK) do
    local sec = cb.add_section()
    for i, name in pairs(names) do sec.set_slot(i, {value = {type = "item", name = name, quality = "normal"}, min = 1}) n = n + 1 end
  end
  return n
end
